"""Calendar authority, private notification routing, catch-up and actual forms."""
from simcore import *
for name in ['Chris Baker','Tyler Baker','Pip Baker']: clients[name]=Client(name)
tick(120)
A,B,P=(clients[n] for n in ['Chris Baker','Tyler Baker','Pip Baker'])
def put(key,value):
    for c in clients.values():c.rt.globals()[key]=value
event=B.ev("__ns.SaveGuildEvent({title='Casual dungeon night',zone='Stormwind',note='Learning welcome',starts=__now+3600,minutes=90,slots=5})")
put('event',event)
check('ordinary members can organise an event',event is not None)
check('organiser has one going response',B.ev('__ns.EventCounts(event).going')==1)
check('event reaches guildmates through paced sync',tick_until(lambda:A.ev('__ns.CasualStore().guildEvents[event]') is not None,60))
A.ex("__ns.RespondGuildEvent(event,'going','h','Happy to heal')")
P.ex("__ns.RespondGuildEvent(event,'tentative','t','May be late')")
check('simultaneous event signups survive merging',tick_until(lambda:B.ev('__ns.EventCounts(event).going')==2 and B.ev('__ns.EventCounts(event).tentative')==1,60))
P.ex("__ns.RespondGuildEvent(event,'going','t','Available')")
check('updating interest does not create another signup',tick_until(lambda:B.ev('__ns.EventCounts(event).going')==3,60) and B.ev('#__ns.EventResponses(event)')==3)
P.ex("__ns.RespondGuildEvent(event,'declined','t','Cannot make it')")
check('declining clears the going count',tick_until(lambda:B.ev('__ns.EventCounts(event).going')==2 and B.ev('__ns.EventCounts(event).declined')==1,60))
check('declining unfollows event updates',not P.ev('__ns.CommunityState().followed[__ns.PersonalToken("event",event)]'))
A.ex("local r={} for k,v in pairs(__ns.CasualStore().guildEvents[event]) do r[k]=v end; r.title='Forged'; r.t=__now+2; __ns.Merge('Pip Baker',{guildEvents={[event]=r}})")
check('member cannot edit another organiser event',A.ev('__ns.CasualStore().guildEvents[event].title')=='Casual dungeon night')
check('member cannot cancel another organiser event',P.ev('__ns.CancelGuildEvent(event)') is False)
check('invalid date range is rejected',B.ev("__ns.SaveGuildEvent({title='Too far',starts=__now+40*86400,minutes=60})") is None)
check('invalid duration is rejected',B.ev("__ns.SaveGuildEvent({title='Too long',starts=__now+600,minutes=481})") is None)

# Conversion uses one absolute instant, with local input round-trip and realm
# wall fields independent of the test host timezone.
A.ex("""__target=math.floor((__now+7200)/60)*60; __wall=date('%Y-%m-%d %H:%M',__target)
local epoch=__now+19800; local c=date('!*t',epoch)
C_DateAndTime={GetCurrentCalendarTime=function() return {year=c.year,month=c.month,monthDay=c.day,hour=c.hour,minute=c.min} end}
""")
check('local event date round-trips to exact shared instant',A.ev('__ns.ParseEventLocal(__wall)')==A.ev('__target'))
check('invalid calendar dates are not normalised silently',A.ev("__ns.ParseEventLocal('2027-02-30 20:00')") is None)
check('invalid hour is rejected',A.ev("__ns.ParseEventLocal('2027-01-15 25:00')") is None)
check('server calendar offset handles half-hour zones',A.ev('__ns.ServerClockOffset()')==19800)
check('server display is independent of host local timezone',A.ev('select(2,__ns.EventTimes(__target))')==A.ev("date('!%Y-%m-%d %H:%M',__target+19800)"))
A.ex('C_DateAndTime=nil')
check('unavailable realm calendar is labelled accurately',A.ev('select(2,__ns.EventTimes(__target))')=='Unavailable')

check('default notification mode preserves instant notices',A.ev('__ns.NotificationPolicy("requests")')=='instant')
A.ex("__ns.CommunityState().mode='digest'; __log={}; __ns.Notify('Request updated','Ready',nil,{category='requests',kind='request',key='r1',revision=1})")
check('digest suppresses popup chat output',A.ev('#__log')==0)
check('digest retains the notice privately',A.ev('(function() local n=0 for _ in pairs(__ns.CommunityState().inbox) do n=n+1 end return n end)()')>=1)
A.ex("__n=0; for _ in pairs(__ns.CommunityState().inbox) do __n=__n+1 end; __ns.Notify('Request updated','Ready',nil,{category='requests',kind='request',key='r1',revision=1})")
check('identical notice revision is deduplicated',A.ev('(function() local n=0 for _ in pairs(__ns.CommunityState().inbox) do n=n+1 end return n end)()')==A.ev('__n'))
A.ex("__ns.MuteUpdates('project','p1',true); __ns.CommunityState().mode='instant'")
check('per-post mute overrides instant mode',A.ev('__ns.NotificationPolicy("projects","p1","project")')=='off')
A.ex("__ns.CommunityState().categories.crafts='off'")
check('category can be silenced independently',A.ev('__ns.NotificationPolicy("crafts")')=='off' and A.ev('__ns.NotificationPolicy("requests")')=='instant')
A.ex("__ns.CommunityState().mode='off'; __ns.CommunityState().categories.requests='instant'")
check('global off takes precedence over category instant',A.ev('__ns.NotificationPolicy("requests")')=='off')
A.ex("__ns.CommunityState().mode='instant'; __realDate=date; date=function(fmt,t) if fmt=='%H:%M' then return __clock or '23:30' end return __realDate(fmt,t) end")
check('overnight quiet hours can be saved',A.ev("__ns.SetQuietHours('22:00','07:00')") is True)
check('quiet hours span midnight',A.ev('__ns.InQuietHours()') is True and A.ev('__ns.NotificationPolicy("requests")')=='digest')
A.ex("__clock='07:00'")
check('quiet hours end at the configured time',not A.ev('__ns.InQuietHours()'))
check('invalid quiet times are rejected',A.ev("__ns.SetQuietHours('25:00','07:00')") is None)
check('both blank quiet times disable quiet hours',A.ev("__ns.SetQuietHours('','')") is True)
A.ex('date=__realDate')

# New features notify followed items, but syncing history stays quiet.
A.ex("__ns.CommunityState().mode='digest'; __ns.FollowUpdates('event',event,true)")
B.ex("local e=__ns.CasualStore().guildEvents[event]; __ns.SaveGuildEvent({title=e.title,zone=e.zone,note='Meet fifteen minutes early',starts=e.starts,minutes=90,slots=5},event)")
check('followed event edits reach members',tick_until(lambda:A.ev('__ns.CasualStore().guildEvents[event].note')=='Meet fifteen minutes early',60))
check('followed event update reaches digest',A.ev('(function() for _,n in pairs(__ns.CommunityState().inbox) do if n.kind=="event" and n.key==event then return true end end return false end)()'))
A.ex("__ns.CasualStore().guildEvents[event].starts=math.floor(__now+600); __ns.CommunityState().seen={}; __ns.CommunityState().inbox={}; __ns.CheckEventReminders(); __ns.CheckEventReminders()")
check('event reminder is queued once for a start time',A.ev('(function() local n=0 for _,v in pairs(__ns.CommunityState().inbox) do if v.category=="reminders" then n=n+1 end end return n end)()')==1)
A.ex("__ns.QueueCommunityNotice('events','event',event,'Event updated','Another reply',99); __ns.CommunityState().inbox={}; __ns.CheckEventReminders()")
check('other event notices do not reset reminder deduplication',A.ev('next(__ns.CommunityState().inbox)==nil'))
A.ex("__ns.CommunityState().mode='digest'; __ns.PostNews('Returning news','A guild update'); __project=__ns.CreateProject('Guild bags','More bags for members')")
check('catch-up includes unread news and active projects',A.ev('(function() local news,project=false,false for _,r in ipairs(__ns.CatchupEntries()) do news=news or r.kind=="news"; project=project or r.kind=="project" end return news and project end)()'))
A.ex("local s=__ns.CommunityState(); s.inbox={sample={title='Digest item',text='Saved',at=__now}}; __ns.MarkCatchupReviewed()")
check('review clears private digest without hiding active projects',A.ev('next(__ns.CommunityState().inbox)==nil') and A.ev('(function() for _,r in ipairs(__ns.CatchupEntries()) do if r.kind=="project" then return true end end return false end)()'))
check('personal notification state never enters shared guild records', 'selectedQuests' not in A.ev('__ns.Serialize(__ns.G())') and 'quietStart' not in A.ev('__ns.Serialize(__ns.G())'))
A.ex("__digest=__ns.EmptyDigest(); __digest.since=__now+999; __digest.fields={}; __delta=__ns.Delta(__digest); __parts=__ns.SplitDelta(__delta)")
check('events and signups participate in digest recovery',A.ev('__delta.guildEvents~=nil and __delta.eventResponses~=nil'))
check('event records survive sync bundling',A.ev('(function() for _,p in ipairs(__parts) do if p.guildEvents then return true end end return false end)()'))
check('officers can cancel an event',A.ev('__ns.CancelGuildEvent(event)') is True)
check('cancellation reaches organiser',tick_until(lambda:B.ev('__ns.CasualStore().guildEvents[event].status')=='cancelled',60))
B.ex("local r={} for k,v in pairs(__ns.CasualStore().guildEvents[event]) do r[k]=v end; r.status='scheduled'; r.t=__now+5; __ns.Merge('Tyler Baker',{guildEvents={[event]=r}})")
check('cancelled events do not resurrect from stale edits',B.ev('__ns.CasualStore().guildEvents[event].status')=='cancelled')
check('cancelled event rejects signups',P.ev("__ns.RespondGuildEvent(event,'going','d','')") is None)

for c in [A,B]:
    c.ex("__ns.UI:Show(); __ns.UI:SetView('activities')")
    for command in ['quests','catchup','notifications']:
        c.ex(f"SlashCmdList.EPUGUILD('{command}')")
    c.ex("SlashCmdList.EPUGUILD('calendar')")
    for kind,key in [('eventform','new'),('event',event),('questsettings','settings'),('noticeform','all'),('noticeform','requests'),('catchupreview','review')]:
        c.rt.globals()['screenKey']=key;c.ex(f"__ns.UI:OpenDetails('{kind}',screenKey)")
    c.ex("__ns.UI:OpenDetails('eventform','new'); __ns.UI.details.pools.box[1]:SetText('Draft event title'); __ns.UI:Refresh()")
    check('background refresh preserves event drafts for '+c.name,c.ev('__ns.UI.details.pools.box[1]:GetText()')=='Draft event title')
A.ex("""function __click(label) for _,b in ipairs(__ns.UI.details.pools.btn) do if b:IsShown() and b.text:GetText()==label then b:GetScript('OnClick')(b); return end end error('Missing button '..label) end
__ns.UI:OpenDetails('eventform','new'); local b=__ns.UI.details.pools.box
b[1]:SetText('UI social event'); b[2]:SetText('Stormwind'); b[3]:SetText('Come and chat'); b[4]:SetText(date('%Y-%m-%d %H:%M',__now+7200)); b[5]:SetText('60'); b[6]:SetText('10'); __click('Create event')
""")
check('event form creates a real event and opens it',A.ev('__ns.UI.details.kind')=='event' and A.ev('__ns.CasualStore().guildEvents[__ns.UI.details.key].title')=='UI social event')
A.ex("__ns.UI:OpenDetails('noticeform','all'); __click('digest'); __ns.UI.details.pools.box[1]:SetText('23:00'); __ns.UI.details.pools.box[2]:SetText('06:00'); __ns.UI.details.pools.box[3]:SetText('20'); __click('Save quiet hours')")
check('notification form saves mode quiet hours and reminder lead',A.ev('__ns.CommunityState().mode')=='digest' and A.ev('__ns.CommunityState().quietStart')=='23:00' and A.ev('__ns.CommunityState().reminderMinutes')==20)
check('new screens produce no runtime errors',sum(c.ev('__errors') or 0 for c in clients.values())==0)
N=Client('Newbie Stone')
N.ex("""__advance(120); local g=__ns.GuildStore(); g.news.test={title='Catch-up news',text='Welcome back',by='Chris Baker',t=__now,u=__now}
local s=__ns.CommunityState(); s.mode='digest'; __dialogs={}; __ns.ShowUnreadNews()
""")
check('news popups obey digest preference',N.ev('#__dialogs')==0 and N.ev('next(__ns.CommunityState().inbox)~=nil'))
N.ex('__ns.ShowUnreadNews(true)')
check('explicitly opening news still works in digest mode',N.ev('#__dialogs')==1)
N.ex("""local real=__ns.CommunityState; local s=real(); s.mode='instant'; s.quietStart=nil; s.quietEnd=nil
__ns.CommunityState=function() return s,__now-2*86400 end; __log={}
__firstHint=__ns.MaybeReturningHint(); __secondHint=__ns.MaybeReturningHint(); __ns.CommunityState=real""")
check('returning-player hint appears once without a popup',N.ev('__firstHint') is True and N.ev('__secondHint') is False and N.ev('#__log')==1)
N.ex("""local s=__ns.CommunityState(); s.mode='instant'; s.sound=false; __sounds=0; PlaySound=function() __sounds=__sounds+1 end
__ns.Notify('Silent notice','First',nil,{category='requests',kind='request',key='sound1',revision=1})
__ns.Notify('Queued notice','Second',nil,{category='requests',kind='request',key='sound2',revision=1})
s.mode='off'; __advance(7)""")
check('personal sound control silences notice sounds',N.ev('__sounds')==0)
check('queued popup respects a later off setting',not N.ev('EPUGuildToast:IsShown()'))
N.ex("""local s=__ns.CommunityState(); s.mode='digest'; for i=1,550 do __ns.RoutePersonalNotice('Test','bounded',nil,{category='requests',kind='request',key='bound'..i,revision=1}) end
__inboxN=0; __seenN=0; for _ in pairs(s.inbox) do __inboxN=__inboxN+1 end; for _ in pairs(s.seen) do __seenN=__seenN+1 end""")
check('personal inbox and dedup history stay bounded',N.ev('__inboxN')==100 and N.ev('__seenN')==500)
N.ex("__ns.UI:Show(); __ns.UI.nav.membertools:Click()")
check('member tools shows all four destinations',N.ev('__ns.UI.rows[1].data.key=="guides" and __ns.UI.rows[2].data.key=="quests" and __ns.UI.rows[3].data.key=="catchup" and __ns.UI.rows[4].data.key=="notifications"'))
for i, tool in enumerate(['guides','quests','catchup','notifications'],1):
    N.ex(f"local row=__ns.UI.rows[{i}]; row:GetScript('OnClick')(row)")
    check(f'member tools row opens {tool}',N.ev(f"__ns.UI.view=='membertools' and __ns.UI.state.membertools.kind=='{tool}'"))
    N.ex("__ns.UI.bars.membertools.allTools:Click()")
N.ex("SlashCmdList.EPUGUILD('notifications')")
check('notifications command opens the same member tools page',N.ev('__ns.UI.view=="membertools" and __ns.UI.state.membertools.kind=="notifications"'))
N.ex("""local s=__ns.CommunityState(); s.mode='instant'; s.quietStart=nil; s.quietEnd=nil
__testEvent=__ns.SaveGuildEvent({title='Reminder navigation',starts=math.floor(__now+3600),minutes=60,slots=5})
__ns.Notify('Event starting soon','Navigation',nil,{category='reminders',kind='event',key=__testEvent,revision='nav'})
EPUGuildToast:GetScript('OnMouseUp')()
""")
check('clicking an event notice opens that event',N.ev('__ns.UI.details.kind')=='event' and N.ev('__ns.UI.details.key')==N.ev('__testEvent'))
N.ex("""for i=1,45 do __ns.Notify('Burst '..i,'Overflow',nil,{category='requests',kind='request',key='burst'..i,revision=1}) end""")
check('instant notice overflow is retained in the digest',N.ev('(function() for _,n in pairs(__ns.CommunityState().inbox) do if n.text=="Overflow" then return true end end return false end)()'))
check('latest same-second notices survive digest trimming',N.ev('__ns.CommunityState().inbox["requests\\030request\\031burst45"]~=nil'))
A.ex("__ns.CommunityState().seen={}; __ns.CommunityState().inbox={}; __ns.CommunityState().mode='digest'; __ns.CheckEventReminders()")
check('trimming generic history cannot replay an event reminder',A.ev('next(__ns.CommunityState().inbox)==nil'))
print('Community tools tests:',check.failed,'failed')
sys.exit(1 if check.failed else 0)
